import{d as l,C as r,o as m,c as h,j as i,a as e,E as a,a3 as d}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"中庸·第1章","description":"《中庸》第 1 章——性、道、教三层纲领，戒慎恐惧与慎独，以及「致中和」：朱熹称此为「一篇之体要」。","frontmatter":{"title":"中庸·第1章","description":"《中庸》第 1 章——性、道、教三层纲领，戒慎恐惧与慎独，以及「致中和」：朱熹称此为「一篇之体要」。","category":"guide","aliases":["第1章","中庸第1章","中庸首章"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-01.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-01.md","lastUpdated":1790316338000}'),y={name:"lizhimingde/sishu-wujing/zhongyong/chapter-01.md"},c=l({...y,setup(p){const o=[{id:"gangling",label:"性—道—教",showLabel:!0,sentences:[[{text:"天命",glossary:"tianming"},"之谓",{text:"性",glossary:"xing"},"；",{text:"率性",glossary:"shuaixing"},"之谓",{text:"道",glossary:"dao"},"；",{text:"修道",glossary:"xiudao"},"之谓",{text:"教",glossary:"jiao"},"。"]],note:"天所赋予人的是「性」，循着性走的是「道」，把这条道修明、推以及人的是「教」——三句一层递一层，是全篇的纲领。",blocks:[{type:"paragraph",text:"注意「率性」不是放任，而是顺着本然的路走；「修道」也不是另造一条道，是把本有的道修明、行出来。"}]},{id:"gongfu",label:"戒慎恐惧与慎独",showLabel:!0,sentences:[["道也者，不可",{text:"须臾",glossary:"xuyu"},"离也；可离，非道也。"],["是故君子",{text:"戒慎",glossary:"jieshen"},"乎其所",{text:"不睹",glossary:"budu"},"，恐惧乎其所",{text:"不闻",glossary:"buwen"},"。"],[{text:"莫见乎隐",glossary:"mojianhuyin"},"，",{text:"莫显乎微",glossary:"moxianhuwei"},"。"],["故君子",{text:"慎其独",glossary:"shendu"},"也。"]],note:"道不可片刻离身，所以要在别人看不见、听不到的地方也守得住。「莫见乎隐，莫显乎微」——愈是隐蔽细微处，愈见一个人的真实，故君子慎独。"},{id:"zhonghe",label:"中与和",showLabel:!0,sentences:[["喜、怒、哀、乐之",{text:"未发",glossary:"weifa"},"，谓之",{text:"中",glossary:"zhong"},"。"],["发而皆",{text:"中节",glossary:"zhongjie"},"，谓之",{text:"和",glossary:"he"},"。"],["中也者，天下之",{text:"大本",glossary:"daben"},"也。和也者，天下之",{text:"达道",glossary:"dadao"},"也。"],[{text:"致中和",glossary:"zhizhonghe"},"，",{text:"天地位",glossary:"tiandiwei"},"焉，",{text:"万物育",glossary:"wanwuyu"},"焉。"]],note:"喜怒哀乐未发时是中，发出来都合节是和。中是天下的大本，和是天下的大道——能「致中和」，天地各安其位、万物各遂其生。"}],s=[{id:"tianming",term:"天命",pinyin:"tiān mìng",meaning:"天所赋予。不是说天在外面下命令，而是说人之为人所本有的那分禀赋，其源头归之于天。"},{id:"xing",term:"性",pinyin:"xìng",meaning:"本性、天理。朱熹注：「性，即理也」——天所命于人的，就是人的性。"},{id:"shuaixing",term:"率性",pinyin:"shuài xìng",meaning:"循性而行。率：循、顺。不是「率性而为」的放任，而是顺着本性本然的路走。"},{id:"dao",term:"道",pinyin:"dào",meaning:"道路、法则。此处指人所当行之路，即循性而行的那条路。"},{id:"xiudao",term:"修道",pinyin:"xiū dào",meaning:"修明此道。修：修治、修明——道本在，但需人把它修明、行出来。"},{id:"jiao",term:"教",pinyin:"jiào",meaning:"教化。把修明之道推以及人，使人皆能由之，就是教。"},{id:"xuyu",term:"须臾",pinyin:"xū yú",meaning:"片刻、极短的时间。"},{id:"jieshen",term:"戒慎",pinyin:"jiè shèn",meaning:"警戒谨慎，常存敬畏之心。"},{id:"budu",term:"不睹",pinyin:"bù dǔ",meaning:"看不见的地方。不睹不闻，指他人耳目所不及之处。"},{id:"buwen",term:"不闻",pinyin:"bù wén",meaning:"听不到的地方。"},{id:"mojianhuyin",term:"莫见乎隐",pinyin:"mò xiàn hū yǐn",meaning:"没有比隐蔽处更显见的。见：通「现」。"},{id:"moxianhuwei",term:"莫显乎微",pinyin:"mò xiǎn hū wēi",meaning:"没有比细微处更显著的。此二句是「慎独」所以必要的理由。"},{id:"shendu",term:"慎其独",pinyin:"shèn qí dú",meaning:"在独处、或人所不知而己独知之地，也守得住。朱注：「独者，人所不知而己所独知之地也。」"},{id:"weifa",term:"未发",pinyin:"wèi fā",meaning:"尚未发动。指喜怒哀乐之情还没有被引发出来的状态。"},{id:"zhong",term:"中",pinyin:"zhōng",meaning:"不偏不倚、中正无过不及。此处特指「未发」时的中正之体。"},{id:"zhongjie",term:"中节",pinyin:"zhòng jié",meaning:"合乎节度。中：符合、恰好；节：法度、节制。音 zhòng。"},{id:"he",term:"和",pinyin:"hé",meaning:"和谐、和顺。情发而皆当于理，无所乖戾，即是和。"},{id:"daben",term:"大本",pinyin:"dà běn",meaning:"天下的根本。「中」为体，万事万物皆由此出。"},{id:"dadao",term:"达道",pinyin:"dá dào",meaning:"天下通行之道。「和」为用，人伦日用皆由此行。"},{id:"zhizhonghe",term:"致中和",pinyin:"zhì zhōng hé",meaning:"把中与和推到极处。致：推极、达到极致。"},{id:"tiandiwei",term:"天地位",pinyin:"tiān dì wèi",meaning:"天地各安其位。位：各当其位、不失其序。"},{id:"wanwuyu",term:"万物育",pinyin:"wàn wù yù",meaning:"万物各遂其生。育：生长化育。"}];return(u,n)=>{const g=r("DaoTextReading"),t=r("DaoKeywordCards");return m(),h("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第1章",tabindex:"-1"},[e("中庸·第1章 "),i("a",{class:"header-anchor",href:"#中庸·第1章","aria-label":'Permalink to "中庸·第1章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("首章是全篇总纲（朱熹称「一篇之体要」）：先立"),i("strong",null,"性—道—教"),e("三层，再讲「不睹不闻」处的工夫，最后落在"),i("strong",null,"中与和"),e("。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(g,{colophon:"性—道—教 · 戒慎恐惧 · 中与和",tone:"ink",sections:o,glossary:s,"default-mode":"slips","aria-label":"中庸·第1章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"天命",pinyin:["tiān","mìng"],meaning:"天所赋予。不是说天在外面下命令，而是说人之为人所本有的那分禀赋，其源头归之于天。"},{term:"性",pinyin:["xìng"],meaning:"本性、天理。朱熹注：「性，即理也」——天所命于人的，就是人的性。"},{term:"率性",pinyin:["shuài","xìng"],meaning:"循性而行。率：循、顺。不是「率性而为」的放任，而是顺着本性本然的路走。"},{term:"道",pinyin:["dào"],meaning:"道路、法则。此处指人所当行之路，即循性而行的那条路。"},{term:"修道",pinyin:["xiū","dào"],meaning:"修明此道。修：修治、修明——道本在，但需人把它修明、行出来。"},{term:"教",pinyin:["jiào"],meaning:"教化。把修明之道推以及人，使人皆能由之，就是教。"},{term:"中庸",pinyin:["zhōng","yōng"],meaning:"不是折中、不是和稀泥，而是「无过不及」的恰当与恒常。庸：常、平常。朱注「中者，不偏不倚、无过不及之名；庸，平常也」。"}]}),a(t,{items:[{term:"须臾",pinyin:["xū","yú"],meaning:"片刻、极短的时间。"},{term:"戒慎",pinyin:["jiè","shèn"],meaning:"警戒谨慎，常存敬畏之心。"},{term:"不睹",pinyin:["bù","dǔ"],meaning:"看不见的地方。不睹不闻，指他人耳目所不及之处。"},{term:"不闻",pinyin:["bù","wén"],meaning:"听不到的地方。"},{term:"莫见乎隐",pinyin:["mò","xiàn","hū","yǐn"],meaning:"没有比隐蔽处更显见的。见：通「现」。"},{term:"莫显乎微",pinyin:["mò","xiǎn","hū","wēi"],meaning:"没有比细微处更显著的。此二句是「慎独」所以必要的理由。"},{term:"慎其独",pinyin:["shèn","qí","dú"],meaning:"在独处、或人所不知而己独知之地，也守得住。朱注：「独者，人所不知而己所独知之地也。」"}]}),a(t,{items:[{term:"未发",pinyin:["wèi","fā"],meaning:"尚未发动。指喜怒哀乐之情还没有被引发出来的状态。"},{term:"已发",pinyin:["yǐ","fā"],meaning:"情已发动之后。与「未发」相对，是心性工夫的一对基本语汇；后世理学「中和」之辨即由此出。"},{term:"中",pinyin:["zhōng"],meaning:"不偏不倚、中正无过不及。此处特指「未发」时的中正之体。"},{term:"中节",pinyin:["zhòng","jié"],meaning:"合乎节度。中：符合、恰好；节：法度、节制。音 zhòng。"},{term:"和",pinyin:["hé"],meaning:"和谐、和顺。情发而皆当于理，无所乖戾，即是和。"},{term:"大本",pinyin:["dà","běn"],meaning:"天下的根本。「中」为体，万事万物皆由此出。"},{term:"达道",pinyin:["dá","dào"],meaning:"天下通行之道。「和」为用，人伦日用皆由此行。"},{term:"致中和",pinyin:["zhì","zhōng","hé"],meaning:"把中与和推到极处。致：推极、达到极致。"},{term:"天地位焉",pinyin:["tiān","dì","wèi","yān"],meaning:"天地各安其位。位：各当其位、不失其序。不是说天地被挪动了，而是说秩序因中和而正。"},{term:"万物育焉",pinyin:["wàn","wù","yù","yān"],meaning:"万物各遂其生。育：生长化育。"}]}),n[4]||(n[4]=d('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>性—道—教</strong>：天所赋予的叫作性；顺着性走叫作道；把这条道修明开来叫作教。</p><p><strong>戒慎恐惧与慎独</strong>：道，是一刻也不能离开的；能离开的，就不是道。所以君子在看不见的地方也警戒谨慎，在听不到的地方也敬畏戒惧。没有比隐蔽处更显见的，没有比细微处更显著的——所以君子在独处时也守得住。</p><p><strong>中与和</strong>：喜怒哀乐还没有发动时的中正，叫作「中」；发动出来而都合乎节度，叫作「和」。「中」，是天下的根本；「和」，是天下通行的道。把中与和推到极处，天地就各安其位，万物就各遂其生。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第一章是全篇的<strong>总纲</strong>。它用三句话立起三层：「天命之谓性」说人的来处，「率性之谓道」说人该走的路，「修道之谓教」说这条路如何被修明、传下去。接着一转，说这条道不能须臾离——<strong>能离的就不是道</strong>——所以在「不睹不闻」处也要守，这才引出「慎独」。</p><p>最后落到「中」与「和」：情未发时的中正叫中，发而皆合节度叫和；中是<strong>大本</strong>（体），和是<strong>达道</strong>（用）。推到极处，便是「天地位焉，万物育焉」。</p><p>结构上它是<strong>从天道说回人心，再从人心推回天地</strong>：性—道—教（由天到人），戒慎恐惧—慎独（人在暗处的守），中—和—致中和（由人到天）。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把「天命」从外面收进了里面</strong>：天命不是外来的一道命令，而是人之为人的本然。这是中国思想「内在性」一维的起点——「听天命」与「做自己」在这里是同一件事。</li><li><strong>它给「道」立了一个可检验的标准</strong>：「可离，非道也」。凡能被离开的（情绪、形势、一时之念），都不是根本。</li><li><strong>「莫见乎隐，莫显乎微」是慎独的理由</strong>：不是道德监视，而是——<strong>最隐蔽处恰恰最显见</strong>。没人看见时你怎么做，才是你真实的样子。</li><li><strong>「中和」成了后世心性工夫的通用语汇</strong>：未发之中是体，发而中节之和是用；一体一用，把「静时守什么」与「动时怎么验」一次说清。</li><li><strong>与《大学》恰成一对</strong>：《大学》由外而内（格致诚正、修齐治平），《中庸》由内而外（性—道—教—天）。先读大学再看首章，两条路径的交点正是「慎独」。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用「能不能离」检验事情</strong>：手里正在做的事、正在执的念，离得开吗？离得开的多半不是根本（「可离，非道也」）。</li><li><strong>把考验放回无人处</strong>：真正的分水岭不在公开场合，而在没人看见、没人知道的地方。</li><li><strong>分清「体」与「用」</strong>：未发之中是根，发而中节是验。平时先养前者，遇事再看后者——只做后者，就成了随事应付。</li><li><strong>重新理解「中」</strong>：中不是中间值，而是<strong>不偏不倚、无过不及</strong>；中庸之「庸」更是「平常」——把恰当做成日常，而不是偶尔的漂亮。</li><li><strong>让「和」落在节度上</strong>：情绪本身没有错，关键是「发而皆中节」——该怒时怒、该喜时喜，而都合于分寸。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>第一章其实就在讲三件事：<strong>人从哪来、路怎么走、怎么知道走对了</strong>。</p><ul><li><strong>从哪来</strong>：天给你的那分样子，就是你的性；顺着这个性走，就是道；把这条道修明、让人也能走，就是教。所以「道」不在远方，就在你本来该有的样子里。</li><li><strong>怎么走</strong>：这条路一刻也离不开——<strong>能被离开的，都不是它</strong>。因此真正的守，不是在众人前守，而是在没人看见、没人听见的地方守；因为最隐蔽处反倒最显见，最细微处反倒最显著。</li><li><strong>怎么知道走对了</strong>：看两处。一处是<strong>情还没起来时的状态</strong>（未发之中）——心里是否中正不偏；一处是<strong>情起来之后的样子</strong>（发而中节之和）——喜怒哀乐发出时，是否都合分寸。前者是根，后者是验。</li></ul><p>它的结论很大：「致中和，天地位焉，万物育焉。」——把中与和推到极处，天地各安其位，万物各遂其生。这不是夸张：一个人内在的秩序，最终会表现在他与世界的关系里。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「天命之谓性」——如果天命就在自己的性中，「听天命」和「做自己」是不是同一件事？</li><li>「戒慎乎其所不睹，恐惧乎其所不闻」——在无人处、在连数据与算法也未必看得见的暗处，这句话今天意味着什么？</li><li>「喜怒哀乐之未发，谓之中」——「未发」是一种能被自己体验到的状态，还是只是理论的设定？我有没有过那样的时刻？</li><li>「发而皆中节」——难处不在「发」，而在「节」：我的「节」由谁定？</li><li>「致中和，天地位焉，万物育焉」——把个人的情绪安顿好，真能通向天地的秩序吗？我愿意信到什么程度？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-02">中庸·第2章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{b as __pageData,c as default};
